\title{The General Conic Classification of Morphogenesis:\\
Turing Patterns as Algebraic Varieties}
\author{Aristotle}
\date{2026-07-10}

\begin{document}

\begin{abstract}
We develop a coordinate-free, algebraic-geometric classification of near-onset
Turing patterns. Reaction--diffusion systems produce spatial patterns whose local
morphology, near the threshold of instability, is governed by a leading quadratic
form $q(x,y) = ax^2 + bxy + cy^2$; the observable morphology is the level set
$\{q = k\}$. We prove that the entire spot/labyrinth dichotomy of morphogenesis is
controlled by a single rotation-invariant quantity, the \emph{discriminant}
$\Disc = b^2 - 4ac$, and that this holds with the cross term $bxy$ present, i.e.
for anisotropic patterns in arbitrary orientation. When $a>0$ and $\Disc<0$
(positive definite) the level set is compact---a \emph{spot}---with an explicit disc
bound of squared radius $4k(a+c)/(4ac-b^2)$; when $a>0$ and $\Disc>0$ (indefinite)
the level set is unbounded---a \emph{labyrinth}---and we exhibit an explicit escaping
one-parameter family. We upgrade the bounded case to a topological statement (the
level set is compact via Heine--Borel) and deduce that spot and labyrinth level sets,
even at equal thresholds, are never the same subset of the plane. On the
mode-counting side we sharpen the ``modes $=$ degree'' correspondence into a
compositional law: via $\cos(n\theta) = T_n(\cos\theta)$, a product of an $m$-mode
and an $n$-mode has degree exactly $m+n$, and a two-mode superposition with nonzero
top harmonic has degree exactly the top mode number.
\end{abstract}

\maketitle

\section{Introduction}

Alan Turing's 1952 theory of morphogenesis proposed that stable spatial
patterns---spots, stripes, spirals, labyrinths---arise spontaneously in
reaction--diffusion systems through a diffusion-driven instability. The patterns
solve nonlinear partial differential equations
$\partial_t u = D\,\Delta u + f(u)$, which are analytically intractable in general.

We pursue a different route. Near the onset of the Turing instability, the emergent
pattern is dominated by a few critical Fourier modes and its local morphology is
captured by a \emph{leading quadratic form}. We show that the qualitative geometry
of the pattern is completely determined by classical invariants---the discriminant
of a conic and the degree of a polynomial---recasting the morphology problem as one
in real algebraic geometry. This translation is exact, coordinate-free, and stable
under the operations by which modes combine. Our contributions are: a discriminant
dichotomy for anisotropic forms (Theorems~\ref{thm:bounded} and \ref{thm:unbounded});
a topological upgrade to compactness (Theorem~\ref{thm:compact}); a separation
theorem (Theorem~\ref{thm:capstone}); and an exact compositional degree calculus for
modes (Theorems~\ref{thm:product} and \ref{thm:super}).

\section{Definitions and setup}

Coordinates $(x,y)$ range over $\R^2$ and all constants are real.

\begin{definition}[Leading quadratic form]
A \emph{leading quadratic form} is $q(x,y) = a\,x^2 + b\,x\,y + c\,y^2$ with
$a,b,c\in\R$. The cross-term coefficient $b$ encodes anisotropy: $b\neq0$ means the
principal axes are not aligned with the coordinate axes.
\end{definition}

\begin{definition}[Pattern level set]
For $k\in\R$, the \emph{level set} is $V_k(q) = \{(x,y)\in\R^2 : q(x,y)=k\}$, the
locus where the morphogen concentration equals $k$. Geometrically it is a conic.
\end{definition}

\begin{definition}[Discriminant]
The \emph{discriminant} of $q$ is $\Disc = b^2 - 4ac$. It is invariant under
rotation of the frame; its sign classifies the conic.
\end{definition}

\begin{definition}[Definiteness]
$q$ is \emph{positive definite} if $q(x,y)>0$ for all $(x,y)\neq(0,0)$, equivalently
$a>0$ and $\Disc<0$; it is \emph{indefinite} if it takes both signs, equivalently
(for $a>0$) $\Disc>0$.
\end{definition}

\begin{definition}[Spot and labyrinth]
$V_k(q)$ is a \emph{spot} if bounded and a \emph{labyrinth} if unbounded.
\end{definition}

\begin{definition}[Mode / Chebyshev encoding]
An \emph{$n$-mode} is $\theta\mapsto\cos(n\theta)$. By the Chebyshev identity
$\cos(n\theta)=T_n(\cos\theta)$, with $T_n\in\R[X]$ of degree exactly $n$; under
$X=\cos\theta$ every mode is a polynomial whose degree equals its mode number.
\end{definition}

\section{Positive-definite forms: spots are compact}

\begin{theorem}[Positive semidefiniteness]\label{thm:psd}
If $a>0$ and $b^2\le 4ac$, then $a x^2 + b x y + c y^2 \ge 0$ for all $(x,y)$.
\end{theorem}

\begin{proof}[Proof sketch]
Multiply by $4a>0$ and complete the square:
$4a\,q = (2ax+by)^2 + (4ac-b^2)y^2$. Both terms are non-negative, so $4a\,q\ge0$,
hence $q\ge0$.
\end{proof}

\begin{theorem}[Spots are bounded]\label{thm:bounded}
Let $a>0$ and $b^2<4ac$. Then for every $k$, $V_k(q)$ lies in the disc of squared
radius $R = 4k(a+c)/(4ac-b^2)$: every solution satisfies $x^2+y^2\le R$.
\end{theorem}

\begin{proof}[Proof sketch]
Positive definiteness gives $c>0$ and $4ac-b^2>0$. From
$(2ax+by)^2\ge0$ and $(bx+2cy)^2\ge0$ one obtains
$(4ac-b^2)y^2\le 4ak$ and $(4ac-b^2)x^2\le 4ck$; adding and dividing by
$4ac-b^2>0$ yields $x^2+y^2\le 4k(a+c)/(4ac-b^2)$.
\end{proof}

\begin{theorem}[Spots are compact]\label{thm:compact}
Under the same hypotheses, $V_k(q)$ is a compact subset of $\R^2$.
\end{theorem}

\begin{proof}[Proof sketch]
$V_k(q)$ is closed (a level set of the continuous map
$(x,y)\mapsto ax^2+bxy+cy^2$) and bounded (Theorem~\ref{thm:bounded}, inside the
ball of radius $\sqrt R$). By Heine--Borel, closed and bounded in $\R^2$ implies
compact.
\end{proof}

\section{Indefinite forms: labyrinths are unbounded}

\begin{theorem}[Labyrinths are unbounded]\label{thm:unbounded}
Let $a>0$ and $\Disc=b^2-4ac>0$. Then for every $k$ and every $R$, $V_k(q)$
contains a point with $x^2+y^2>R$.
\end{theorem}

\begin{proof}[Proof sketch]
Complete the square in the indefinite direction:
$4a\,q = (2ax+by)^2 - \Disc\,y^2$. Set $y=s$ with
$s=\sqrt{|R| + |4ak/\Disc| + 1}$, so that $W:=\Disc s^2 + 4ak>0$, and take
$x=(\sqrt W - bs)/(2a)$. Then $q(x,s)=k$ and $x^2+y^2\ge s^2 > R$; letting
$R\to\infty$ gives points escaping to infinity along the hyperbola's arms.
\end{proof}

\section{Modes and degree: an exact compositional calculus}

\begin{theorem}[Products multiply degree]\label{thm:product}
For all $m,n\in\N$ there is $P\in\R[X]$ of degree exactly $m+n$ with
$P(\cos\theta)=\cos(m\theta)\cos(n\theta)$ for all $\theta$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $P=T_m T_n$. Each $T_j\neq0$ has degree exactly $j$, and degree is additive
under multiplication of nonzero polynomials, so $\deg P = m+n$; the identity follows
from $T_j(\cos\theta)=\cos(j\theta)$.
\end{proof}

\begin{theorem}[Superposition is degree-stable]\label{thm:super}
Let $m<n$, $\alpha,\beta\in\R$, $\beta\neq0$. Then there is $P\in\R[X]$ of degree
exactly $n$ with $P(\cos\theta)=\alpha\cos(m\theta)+\beta\cos(n\theta)$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $P=\alpha T_m + \beta T_n$. The term $\beta T_n$ has degree exactly $n$ (as
$\beta\neq0$) and strictly dominates $\alpha T_m$ (degree $\le m<n$), so
$\deg P = n$.
\end{proof}

\section{Capstone: spots and labyrinths are distinct varieties}

\begin{theorem}[Discriminant morphological dichotomy]\label{thm:capstone}
Let $q$ be positive definite ($a>0$, $b^2<4ac$) and $q'$ indefinite ($a'>0$,
$b'^2-4a'c'>0$). Then for every $k$, $V_k(q)\neq V_k(q')$.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:bounded} there is $R$ bounding $V_k(q)$. By
Theorem~\ref{thm:unbounded}, $V_k(q')$ has a point of squared norm $>R$. Were the
sets equal, that point would satisfy both, a contradiction.
\end{proof}

\section{Algorithms}

\begin{algorithm}[Discriminant classifier]
Given $a,b,c$, compute $\Disc=b^2-4ac$. If $a>0,\Disc<0$: spot (with radius
$\sqrt{4k(a+c)/(4ac-b^2)}$). If $\Disc>0$: labyrinth. If $\Disc=0$: degenerate.
$O(1)$.
\end{algorithm}

\begin{algorithm}[Spot radius certificate]
Given positive-definite $a,b,c$ and $k$, return $R=4k(a+c)/(4ac-b^2)$; every
solution point satisfies $x^2+y^2\le R$. $O(1)$.
\end{algorithm}

\begin{algorithm}[Labyrinth escape sampler]
Given indefinite $a,b,c$, $k$, and target $R$: set
$s=\sqrt{|R|+|4ak/\Disc|+1}$, $W=\Disc s^2+4ak$, $x=(\sqrt W - bs)/(2a)$, $y=s$.
$O(1)$.
\end{algorithm}

\begin{algorithm}[Mode--degree calculator]
For a pattern built from modes by products and sums: product $m,n\mapsto m+n$; sum
with distinct top harmonic $\mapsto\max$. Linear in the number of terms.
\end{algorithm}

\section{Applications and discussion}

The discriminant $\Disc=b^2-4ac$ is the correct invariant because it is
rotation-invariant: no proof assumes frame alignment, so every statement survives
arbitrary rotation---essential since physical patterns carry a nonzero cross term.
Applications include automatic morphology classification from fitted forms,
quantitative spot sizing via the explicit radius, rigorous complexity metering via
the degree calculus, and stability screening (the dichotomy is an open condition).
The compactness upgrade lifts the spot property from a metric accident to a
topological invariant, unlocking Heine--Borel and, downstream, Morse-theoretic
counting. A limitation is that the analysis is near onset; the nonlinear regime is
addressed conjecturally below.

\section{Future directions}

\begin{conjecture}[Degree--genus law for three-mode flowers]
A generic three-mode planar pattern is the real locus of a sextic whose smooth
complex model has genus $10$; Harnack's bound caps the compact ovals (visible spots)
at $g+1=11$, with hexagonal spot lattices realizing the extremal Harnack curve. Mode
count controls not just degree but genus, so spot combinatorics is governed by the
topology of a Riemann surface; the product/superposition degree laws supply exactly
the input Harnack and Pl\"ucker formulas need.
\end{conjecture}

\begin{conjecture}[Discriminant stability under nonlinear saturation]
For the full nonlinear pattern near onset, the sign of the discriminant of the
linearized leading form is preserved by the weakly nonlinear correction: a spot
stays compact and a labyrinth stays unbounded for all amplitudes below a computable
threshold $A_c$. The dichotomy is an open condition, hence persists under the small
deformation given by the amplitude expansion; the explicit radius and escaping
family make the perturbation effective.
\end{conjecture}

\begin{conjecture}[Compactness $\Rightarrow$ finite spot census]
For positive-definite forms the level set carries a finite computable Euler
characteristic, with spot count $1+(\text{interior critical values crossed})$, and
the coefficient-to-count map is locally constant away from $\Disc=0$. Compactness
makes Morse theory available, so the spot census is a topological invariant.
\end{conjecture}

\section{Conclusion}

The morphology of near-onset Turing patterns is governed by classical invariants of
algebraic geometry. The sign of $\Disc=b^2-4ac$ decides between compact spots and
unbounded labyrinths, coordinate-freely; the spot case is compact; the two
morphologies are provably distinct as subsets of the plane; and the number of active
modes reads off as an exact polynomial degree, additive under products and stable
under superposition.

\end{document}

