"""Demo 3: Exact mode-degree calculus via Chebyshev polynomials.

Confirms cos(n t)=T_n(cos t), that a product of an m-mode and an n-mode has degree
exactly m+n, and that a superposition with nonzero top harmonic has degree exactly
the top mode number.
"""
from __future__ import annotations
from typing import List

def chebyshev_T(n: int) -> List[float]:
    if n == 0:
        return [1.0]
    if n == 1:
        return [0.0, 1.0]
    p2, p1 = [1.0], [0.0, 1.0]
    for _ in range(2, n + 1):
        cur = [2.0 * v for v in ([0.0] + p1)]
        for i, v in enumerate(p2):
            cur[i] -= v
        p2, p1 = p1, cur
    return p1

def poly_degree(c: List[float], tol: float = 1e-12) -> int:
    return max((i for i, v in enumerate(c) if abs(v) > tol), default=0)

def poly_mul(p: List[float], q: List[float]) -> List[float]:
    out = [0.0] * (len(p) + len(q) - 1)
    for i, pi in enumerate(p):
        for j, qj in enumerate(q):
            out[i + j] += pi * qj
    return out

if __name__ == "__main__":
    for m, n in [(2, 3), (3, 4), (5, 2)]:
        d = poly_degree(poly_mul(chebyshev_T(m), chebyshev_T(n)))
        print(f"deg[cos({m}t)cos({n}t)] = {d}  (m+n={m+n})")

