from __future__ import annotations
from typing import Optional, Tuple

def classify_pattern(a: float, b: float, c: float,
                     k: Optional[float] = None) -> Tuple[str, Optional[float]]:
    """Classify a near-onset Turing pattern from its leading quadratic form.

    Returns (morphology, radius_sq) where morphology is 'spot', 'labyrinth', or
    'degenerate'. For spots with k supplied, radius_sq is the certified bound
    4k(a+c)/(4ac-b^2); otherwise None.
    """
    delta = b * b - 4.0 * a * c
    if a > 0 and delta < 0:
        rsq = None
        if k is not None:
            rsq = 4.0 * k * (a + c) / (4.0 * a * c - b * b)
        return ("spot", rsq)
    if delta > 0:
        return ("labyrinth", None)
    return ("degenerate", None)

from __future__ import annotations
from typing import List

def chebyshev_T(n: int) -> List[float]:
    """Ascending coefficients of the Chebyshev polynomial T_n."""
    if n == 0:
        return [1.0]
    if n == 1:
        return [0.0, 1.0]
    p2, p1 = [1.0], [0.0, 1.0]
    for _ in range(2, n + 1):
        cur = [2.0 * v for v in ([0.0] + p1)]
        for i, v in enumerate(p2):
            cur[i] -= v
        p2, p1 = p1, cur
    return p1

def _mul(p: List[float], q: List[float]) -> List[float]:
    out = [0.0] * (len(p) + len(q) - 1)
    for i, pi in enumerate(p):
        for j, qj in enumerate(q):
            out[i + j] += pi * qj
    return out

def _deg(c: List[float], tol: float = 1e-12) -> int:
    return max((i for i, v in enumerate(c) if abs(v) > tol), default=0)

def product_degree(m: int, n: int) -> int:
    """Degree of the polynomial representing cos(m t) cos(n t): equals m+n."""
    return _deg(_mul(chebyshev_T(m), chebyshev_T(n)))

def superposition_degree(m: int, n: int) -> int:
    """Degree of a two-mode superposition with distinct modes: equals max(m,n)."""
    return max(m, n)
